// BuildVersion: 바이너리에 박힌 git 커밋 (go build 가 VCS 정보를 넣는 경우), 없으면 "dev".
func BuildVersion() string {
	if bi, ok := debug.ReadBuildInfo(); ok {
		for _, s := range bi.Settings {
			if s.Key == "vcs.revision" && len(s.Value) >= 7 {
				return s.Value[:7]
			}
		}
	}
	return "dev"
}

// PublishStatus: status.json 을 키별로 갱신한다 (실패해도 매매에는 영향 없음).
func PublishStatus(gh *github.Client, branch string, e StatusEntry) error {
	return gh.UpdateFile("docs/data/status.json", branch, fmt.Sprintf("status(%s): %s", e.Key, e.State), func(existing []byte) ([]byte, error) {
		var list []StatusEntry
		if len(existing) > 0 {
			_ = json.Unmarshal(existing, &list)
		}
		replaced := false
		for i := range list {
			if list[i].Key == e.Key {
				list[i], replaced = e, true
			}
		}
		if !replaced {
			list = append(list, e)
		}
		return json.MarshalIndent(list, "", " ")
	})
